import{_ as i,c as n,o as s,a0 as e}from"./chunks/framework.oTSD2LDJ.js";const u=JSON.parse('{"title":"UniDeskPluginMgr","description":"","frontmatter":{"title":"UniDeskPluginMgr","editLink":true},"headers":[],"relativePath":"controls-reference/cpp-ext/UniDeskPluginMgr.md","filePath":"zh/controls-reference/cpp-ext/UniDeskPluginMgr.md"}'),l={name:"controls-reference/cpp-ext/UniDeskPluginMgr.md"};function t(o,a,d,r,p,h){return s(),n("div",null,a[0]||(a[0]=[e('<h1 id="unideskpluginmgr-类型" tabindex="-1">UniDeskPluginMgr 类型 <a class="header-anchor" href="#unideskpluginmgr-类型" aria-label="Permalink to &quot;UniDeskPluginMgr 类型&quot;">​</a></h1><p>插件管理器，负责扫描并加载 <code>plugins/</code> 目录下的 DLL 插件、管理插件元数据、启停插件，以及向 QML 注册插件提供的类型。</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>控件类型</td><td>全局单例</td></tr><tr><td>源文件</td><td><code>UniDesk/CppExt/UniDeskPluginMgr.h</code> / <code>.cpp</code></td></tr><tr><td>继承</td><td>QQuickItem</td></tr><tr><td>QML 导入</td><td><code>import UniDesk 1.0</code></td></tr></tbody></table><h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2><h3 id="property-bool-isloading" tabindex="-1"><code>property bool isLoading</code> <a class="header-anchor" href="#property-bool-isloading" aria-label="Permalink to &quot;`property bool isLoading`&quot;">​</a></h3><p>是否正在加载插件（可用于 UI 显示加载状态）。</p><h3 id="property-qvariantlist-pluginlist" tabindex="-1"><code>property QVariantList pluginList</code> <a class="header-anchor" href="#property-qvariantlist-pluginlist" aria-label="Permalink to &quot;`property QVariantList pluginList`&quot;">​</a></h3><p>当前已扫描到的插件列表。每项为 <code>QVariantMap</code>，包含 <code>name</code>、<code>version</code>、<code>author</code>、<code>enabled</code> 等元数据。</p><h3 id="property-qstring-plugindir" tabindex="-1"><code>property QString pluginDir</code> <a class="header-anchor" href="#property-qstring-plugindir" aria-label="Permalink to &quot;`property QString pluginDir`&quot;">​</a></h3><p>插件扫描目录，默认为 <code>&lt;应用目录&gt;/plugins/</code>。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="function-loadplugins" tabindex="-1"><code>function loadPlugins()</code> <a class="header-anchor" href="#function-loadplugins" aria-label="Permalink to &quot;`function loadPlugins()`&quot;">​</a></h3><p>从 <code>pluginDir</code> 扫描所有 DLL 文件并尝试加载。对每个有效的插件：</p><ol><li>通过 <code>QPluginLoader</code> 加载</li><li>使用 <code>qobject_cast&lt;UniDeskPluginInterface*&gt;</code> 检查是否实现了插件接口</li><li>依次调用 <code>registerQmlTypes(engine)</code> 和 <code>initialize()</code></li></ol><h3 id="function-unloadplugins" tabindex="-1"><code>function unloadPlugins()</code> <a class="header-anchor" href="#function-unloadplugins" aria-label="Permalink to &quot;`function unloadPlugins()`&quot;">​</a></h3><p>卸载所有已加载的插件，释放 <code>QPluginLoader</code> 并清理引用。</p><h3 id="function-enableplugin-name-enabled" tabindex="-1"><code>function enablePlugin(name, enabled)</code> <a class="header-anchor" href="#function-enableplugin-name-enabled" aria-label="Permalink to &quot;`function enablePlugin(name, enabled)`&quot;">​</a></h3><p>按名称启用或禁用指定插件。</p><h3 id="function-getpluginlist-→-qvariantlist" tabindex="-1"><code>function getPluginList() → QVariantList</code> <a class="header-anchor" href="#function-getpluginlist-→-qvariantlist" aria-label="Permalink to &quot;`function getPluginList() → QVariantList`&quot;">​</a></h3><p>返回当前插件列表（等同于 <code>pluginList</code> 属性）。</p><h3 id="function-refreshpluginlist" tabindex="-1"><code>function refreshPluginList()</code> <a class="header-anchor" href="#function-refreshpluginlist" aria-label="Permalink to &quot;`function refreshPluginList()`&quot;">​</a></h3><p>重新扫描插件目录并刷新 <code>pluginList</code>。</p><h2 id="信号" tabindex="-1">信号 <a class="header-anchor" href="#信号" aria-label="Permalink to &quot;信号&quot;">​</a></h2><h3 id="signal-pluginloaded-name-success" tabindex="-1"><code>signal pluginLoaded(name, success)</code> <a class="header-anchor" href="#signal-pluginloaded-name-success" aria-label="Permalink to &quot;`signal pluginLoaded(name, success)`&quot;">​</a></h3><p>单个插件加载完成时发出，<code>success</code> 表示是否加载成功。</p><h3 id="signal-allpluginsloaded-count" tabindex="-1"><code>signal allPluginsLoaded(count)</code> <a class="header-anchor" href="#signal-allpluginsloaded-count" aria-label="Permalink to &quot;`signal allPluginsLoaded(count)`&quot;">​</a></h3><p>所有插件加载完成后发出，<code>count</code> 为成功加载的数量。</p><h3 id="signal-pluginlistchanged" tabindex="-1"><code>signal pluginListChanged()</code> <a class="header-anchor" href="#signal-pluginlistchanged" aria-label="Permalink to &quot;`signal pluginListChanged()`&quot;">​</a></h3><p>插件列表发生变化时发出。</p><h3 id="signal-pluginerror-name-message" tabindex="-1"><code>signal pluginError(name, message)</code> <a class="header-anchor" href="#signal-pluginerror-name-message" aria-label="Permalink to &quot;`signal pluginError(name, message)`&quot;">​</a></h3><p>插件加载/卸载出错时发出。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> UniDesk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UniDeskPluginMgr.loadPlugins()</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Connections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: UniDeskPluginMgr</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onPluginLoaded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Plugin:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, name, success </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;loaded&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;failed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onAllPluginsLoaded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;All plugins loaded, total:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, count)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="插件目录结构" tabindex="-1">插件目录结构 <a class="header-anchor" href="#插件目录结构" aria-label="Permalink to &quot;插件目录结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/</span></span>\n<span class="line"><span>├── MyPlugin/</span></span>\n<span class="line"><span>│   └── MyPlugin.dll</span></span>\n<span class="line"><span>├── AnotherPlugin/</span></span>\n<span class="line"><span>│   └── AnotherPlugin.dll</span></span>\n<span class="line"><span>└── ...</span></span></code></pre></div><h2 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h2><ul><li>插件通过 <code>QPluginLoader</code> 动态加载，依赖 <code>UniDeskPluginInterface</code> 接口识别。</li><li>加载失败的插件不会影响主程序稳定性，会跳过继续加载下一个。</li><li>插件元数据（<code>name</code>、<code>version</code> 等）来自插件 DLL 内部的 <code>Q_PLUGIN_METADATA</code>。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./UniDeskPluginInterface">UniDeskPluginInterface</a> — 插件开发接口</li><li><a href="./../../custom-developing/plugin">自定义开发：插件</a> — 完整的插件开发流程</li><li><a href="./../../official-plugins">官方插件</a> — 官方插件包使用说明</li></ul>',39)]))}const g=i(l,[["render",t]]);ex